const TradingTrends: React.FC<TradingTrendsProps> = ({
  backgroundColor = "#0d0b0c",
  transparentBackground = false,
  durationInSeconds = 5, // Cut down default duration from 7 to 5 seconds to reduce idle middle time
  logoUrl = "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/12e2926302ef43b9bd3b1b0fc439d5d5.png",
  logoSize = 220,
  titlePart1 = "TRADING",
  titlePart1FontFamily = "TuskerGrotesk-6500Medium",
  titlePart2 = "TRENDS",
  titlePart2FontFamily = "TuskerGrotesk-6500Medium",
  cherryRedColor = "#e21f26",
  textColorPart1 = "#ffffff",
  accentOpacity = 0.35,
  driftSpeed = 1.0,
  fontSize = 320,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const totalFrames = durationInSeconds * fps;
  const outroStartFrame = totalFrames - 24; // Keeps full animation out sequence

  // Continuous background drift variable
  const driftProgress = frame * driftSpeed * 0.18;

  // Responsive calculations matching guidelines
  const responsiveFontSize = fontSize * (width / 1920);
  const responsiveLogoWidth = logoSize * (width / 1920);
  const strokeRatio = Math.max(1, Math.min(width, height) * 0.0018);
  const dotRatio = Math.max(1.5, Math.min(width, height) * 0.002);

  // Background and transparent container resolution
  const resolvedBgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // --- BACKGROUND TRANSITIONS ---
  // Ambient elements slide in smoothly at the start
  const introSpring = spring({
    frame,
    fps,
    config: { damping: 24, mass: 1.2, stiffness: 70 },
  });

  const outroProgress = interpolate(
    frame,
    [outroStartFrame, totalFrames],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.bezier(0.25, 0.1, 0.25, 1.0),
    }
  );

  // Background elements Quick Horizontal Entrance & Exit Transitions
  const bgIntroSpring = spring({
    frame,
    fps,
    config: { damping: 26, mass: 1.3, stiffness: 65 },
  });
  const leftBgIntroX = interpolate(bgIntroSpring, [0, 1], [-450, 0]);
  const rightBgIntroX = interpolate(bgIntroSpring, [0, 1], [450, 0]);

  const leftBgOutroX = interpolate(outroProgress, [0, 0.8], [0, -650], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const rightBgOutroX = interpolate(outroProgress, [0, 0.8], [0, 650], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Continuous upscale and clean, organized linear outward drift motion
  const bgScale = interpolate(frame, [0, totalFrames], [1.0, 1.15], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.25, 0.1, 0.25, 1.0),
  });
  const driftRatio = frame / totalFrames;
  const driftXLeft = -40 * driftRatio * driftSpeed;
  const driftXRight = 40 * driftRatio * driftSpeed;
  const driftY = -20 * driftRatio * driftSpeed;

  // Combined Left-side / Right-side Background element transforms
  const leftBgTransform = `translateX(${leftBgIntroX + leftBgOutroX + driftXLeft}px) translateY(${driftY}px) scale(${bgScale})`;
  const rightBgTransform = `translateX(${rightBgIntroX + rightBgOutroX + driftXRight}px) translateY(${driftY}px) scale(${bgScale})`;

  // Left Panel Intro/Hold/Outro X translation
  const leftPanelXIntro = interpolate(introSpring, [0, 1], [-220, 0]);
  const leftPanelDrift = interpolate(
    frame,
    [14, outroStartFrame],
    [0, -10 * driftSpeed],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );
  const leftPanelXOutro = interpolate(outroProgress, [0, 0.8], [0, -450]);
  const leftPanelX = leftPanelXIntro + leftPanelDrift + leftPanelXOutro;

  // Right Panel Intro/Hold/Outro X translation
  const rightPanelXIntro = interpolate(introSpring, [0, 1], [220, 0]);
  const rightPanelDrift = interpolate(
    frame,
    [14, outroStartFrame],
    [0, 10 * driftSpeed],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );
  const rightPanelXOutro = interpolate(outroProgress, [0, 0.8], [0, 450]);
  const rightPanelX = rightPanelXIntro + rightPanelDrift + rightPanelXOutro;

  // --- LOGO TRANSITIONS ---
  // Logo enters quicker at frame 6, springs cleanly into place
  const logoIntroSpring = spring({
    frame: frame - 6,
    fps,
    config: { damping: 18, mass: 0.9, stiffness: 120 },
  });
  const logoYIntro = interpolate(logoIntroSpring, [0, 1], [-70, 0]);
  const logoOpacityIntro = interpolate(logoIntroSpring, [0, 0.6], [0, 1]);

  // Logo Outro sequence - fast whoosh scale past camera
  const logoOutroProgress = interpolate(
    frame,
    [outroStartFrame, outroStartFrame + 14],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.bezier(0.25, 0.1, 0.25, 1.0),
    }
  );
  const logoScaleOutro = interpolate(logoOutroProgress, [0, 1], [1.0, 16.0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const logoOpacityOutro = interpolate(logoOutroProgress, [0, 0.6], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Combine Logo transforms safely
  const logoY = frame < outroStartFrame ? logoYIntro : 0;
  const logoScale = frame < outroStartFrame ? 1.0 : logoScaleOutro;
  const logoOpacity =
    frame < outroStartFrame ? logoOpacityIntro : logoOpacityOutro;

  // --- TITLE TEXT REVEALS (TRADING THEN TRENDS) ---
  // Word 1: TRADING (reveals quicker at frame 13 with snappy physics, starting slightly lower for larger mask)
  const part1Spring = spring({
    frame: frame - 13,
    fps,
    config: { damping: 18, mass: 0.9, stiffness: 120 },
  });
  const part1Y = interpolate(part1Spring, [0, 1], [responsiveFontSize * 1.2, 0]);
  const part1Opacity = interpolate(part1Spring, [0, 0.5], [0, 1]);

  // Word 2: TRENDS (reveals offset quicker at frame 19 with snappy physics, starting slightly lower for larger mask)
  const part2Spring = spring({
    frame: frame - 19,
    fps,
    config: { damping: 18, mass: 0.9, stiffness: 120 },
  });
  const part2Y = interpolate(part2Spring, [0, 1], [responsiveFontSize * 1.2, 0]);
  const part2Opacity = interpolate(part2Spring, [0, 0.5], [0, 1]);

  // --- CONTINUOUS UPSCALE HOLD & STYLISH OUTRO ---
  // Continuous upscale hold during presentation adjusts to start immediately after the snap in
  const holdProgress = interpolate(
    frame,
    [25, outroStartFrame],
    [1.0, 1.05],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.bezier(0.25, 0.1, 0.25, 1.0),
    }
  );

  // Quick camera whoosh past viewer (exponential scale to 22.0x, instant exit)
  const titleOutroProgress = interpolate(
    frame,
    [outroStartFrame, outroStartFrame + 16],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.bezier(0.25, 0.1, 0.25, 1.0),
    }
  );
  const titleOutroScale = interpolate(titleOutroProgress, [0, 1], [1.0, 22.0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const titleOutroOpacity = interpolate(titleOutroProgress, [0, 0.65], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Consolidated Master Title Transform
  const masterTitleScale =
    frame < outroStartFrame ? holdProgress : holdProgress * titleOutroScale;
  const masterTitleOpacity =
    frame < outroStartFrame ? 1 : titleOutroOpacity;

  // Clean, organized coordinate boundaries for crosshairs centered more nicely
  const crosshairs = [
    { x: "24%", y: "15%" },
    { x: "76%", y: "15%" },
    { x: "26%", y: "85%" },
    { x: "74%", y: "85%" },
    { x: "18%", y: "50%" },
    { x: "82%", y: "50%" },
  ];

  return (
    <AbsoluteFill
      style={{
        backgroundColor: resolvedBgColor,
        overflow: "hidden",
      }}
    >
      {/* Background Grids & Atmospheric Drifts */}
      <GridBackground
        accentColor={cherryRedColor}
        drift={driftProgress}
        opacity={accentOpacity}
      />
      <AtmosphericElements
        accentColor={cherryRedColor}
        drift={driftProgress}
      />

      {/* Textured Financial, Neon & Mathematical Elements in the Background */}
      <OnAirSign color={cherryRedColor} frame={frame} style={{ transform: rightBgTransform }} />
      
      {/* Left side elements - Repositioned closer to center to resolve edge clunkiness and overlap */}
      <ProbabilityCurve 
        color={cherryRedColor} 
        drift={driftProgress} 
        style={{ bottom: "12%", left: "14%", transform: leftBgTransform }} 
        opacity={0.28} 
      />
      <FibonacciSpiral 
        color={cherryRedColor} 
        drift={driftProgress} 
        style={{ top: "10%", left: "15%", width: "240px", height: "240px", transform: leftBgTransform }} 
        opacity={0.22} 
      />
      <MarketImagery 
        color={cherryRedColor} 
        drift={driftProgress} 
        style={{ top: "42%", left: "13%", transform: leftBgTransform }} 
        opacity={0.32} 
      />
      <DotMatrix x="13%" y="35%" color={cherryRedColor} dotSize={dotRatio * 1.5} style={{ transform: leftBgTransform }} />
      <DotMatrix x="19%" y="75%" color={cherryRedColor} dotSize={dotRatio * 1.5} style={{ transform: leftBgTransform }} />

      {/* Right side elements - Repositioned closer to center to resolve edge clunkiness and overlap */}
      <MarketDepthBands 
        color={cherryRedColor} 
        drift={driftProgress} 
        style={{ top: "15%", right: "14%", transform: rightBgTransform }} 
        opacity={0.25} 
      />
      <FibonacciSpiral 
        color={cherryRedColor} 
        drift={driftProgress} 
        style={{ bottom: "12%", right: "15%", width: "240px", height: "240px", transform: rightBgTransform }} 
        opacity={0.28} 
      />
      <MarketImagery 
        color={cherryRedColor} 
        drift={driftProgress} 
        style={{ top: "42%", right: "13%", transform: `${rightBgTransform} scaleX(-1)` }} 
        opacity={0.28} 
      />
      <DotMatrix x="74%" y="30%" color="#ffffff" dotSize={dotRatio * 1.5} style={{ transform: rightBgTransform }} />
      <DotMatrix x="67%" y="78%" color="#ffffff" dotSize={dotRatio * 1.5} style={{ transform: rightBgTransform }} />

      {/* Standard Crosshairs for Broadcast aesthetics - Transitioning smoothly with adjusted central layouts */}
      {crosshairs.map((ch, idx) => {
        const pulse = Math.sin(frame * 0.08 + idx) * 0.2 + 0.65;
        const xPercent = parseFloat(ch.x);
        const transformToUse = xPercent < 50 ? leftBgTransform : rightBgTransform;
        return (
          <div
            key={idx}
            style={{
              position: "absolute",
              left: ch.x,
              top: ch.y,
              color: cherryRedColor,
              opacity: pulse,
              fontSize: 32,
              fontWeight: 900,
              textShadow: `0 0 8px ${cherryRedColor}`,
              transform: `translate(-50%, -50%) ${transformToUse}`,
              userSelect: "none",
              pointerEvents: "none",
              transition: "none",
            }}
          >
            +
          </div>
        );
      })}

      {/* Slanted Side Panels framing the text beautifully */}
      <LeftPanel
        accentColor={cherryRedColor}
        xOffset={leftPanelX}
        opacity={0.95}
        lineWeight={strokeRatio * 1.3}
      />
      <RightPanel
        accentColor={cherryRedColor}
        xOffset={rightPanelX}
        opacity={0.95}
        lineWeight={strokeRatio * 1.3}
      />

      {/* Main Content Lockup Container */}
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "center",
          zIndex: 10,
          pointerEvents: "none",
          transition: "none",
        }}
      >
        {/* tastylive logo centering wrapper with scale whoosh capability */}
        <div
          style={{
            transform: `translateY(${logoY}px) scale(${logoScale})`,
            opacity: logoOpacity,
            marginBottom: height * 0.035,
            transition: "none",
          }}
        >
          <Img
            src={logoUrl}
            style={{
              width: responsiveLogoWidth,
              height: "auto",
              display: "block",
              transition: "none",
            }}
          />
        </div>

        {/* Confident stacked typography wrapper with editorial masks */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
            transform: `scale(${masterTitleScale})`,
            opacity: masterTitleOpacity,
            width: "100%",
            transition: "none",
          }}
        >
          {/* Mask for TRADING - Mask height slightly extended to prevent top cropping of the tall font */}
          <div
            style={{
              height: responsiveFontSize * 1.15,
              overflow: "hidden",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              width: "100%",
              transition: "none",
            }}
          >
            <h1
              style={{
                fontFamily: titlePart1FontFamily,
                color: textColorPart1,
                fontSize: responsiveFontSize,
                fontWeight: "bold",
                textTransform: "uppercase",
                transform: `translateY(${part1Y}px)`,
                opacity: part1Opacity,
                letterSpacing: "-0.015em",
                margin: 0,
                padding: 0,
                textAlign: "center",
                lineHeight: 1.0,
                transition: "none",
              }}
            >
              {titlePart1}
            </h1>
          </div>

          {/* Mask for TRENDS - Mask height slightly extended to prevent top cropping of the tall font */}
          <div
            style={{
              height: responsiveFontSize * 1.15,
              overflow: "hidden",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              width: "100%",
              transition: "none",
            }}
          >
            <h1
              style={{
                fontFamily: titlePart2FontFamily,
                color: cherryRedColor,
                fontSize: responsiveFontSize,
                fontWeight: "bold",
                textTransform: "uppercase",
                transform: `translateY(${part2Y}px)`,
                opacity: part2Opacity,
                letterSpacing: "-0.015em",
                margin: 0,
                padding: 0,
                textAlign: "center",
                lineHeight: 1.0,
                transition: "none",
              }}
            >
              {titlePart2}
            </h1>
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default TradingTrends;